-- =====================================================================
-- Richwell Colleges - Hotel and Restaurant master data seed (2026-11-09)
-- Replaces whatever store is in this database (Crab & Crack, Grumpy Joe,
-- ...) with Richwell: company, business category, business unit, sales
-- types, pricing, 261 products, rooms/floors, discount per sales
-- type and other charges. It CLEARS all existing products, prices, pricing
-- categories, rooms and floors in this database.
--
-- RUN ORDER (back up the database first):
--   1. In the POS: Settings > DB Reset   (clears old transactions, counters,
--      shifts and discount-per-sales-type rows)
--   2. 2026-11-09_richwell_tables_to_rooms.sql
--   3. this file
--   4. Restart the POS / Apache
--
-- Running DB Reset AFTER this file wipes tbl_pos_discount_type_sales_type;
-- re-run this file in that case. Re-running replaces the Richwell product
-- list, prices and rooms with this list (products added later in the app
-- under the Richwell unit are removed), so treat it as an initial seed.
--
-- Codes used
--   Corp_Code      301
--   Category_Code  Richwell
--   Unit_Code      BU-24cae516f663
-- =====================================================================

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `tbl_pos_discount_type_sales_type` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `discount_type_id` INT NOT NULL,
  `sales_type_id` VARCHAR(50) NOT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 0,
  `percent_value` DECIMAL(8,2) NULL,
  `usertracker` VARCHAR(100) NULL,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_discount_sales_type` (`discount_type_id`, `sales_type_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `tbl_pos_tables` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `category_code` VARCHAR(100) NOT NULL,
  `unit_code` VARCHAR(100) NOT NULL,
  `table_name` VARCHAR(100) NOT NULL,
  `transaction_reference` VARCHAR(100) NOT NULL DEFAULT '0',
  `status` VARCHAR(50) NOT NULL DEFAULT 'Available',
  PRIMARY KEY (`ID`),
  KEY `idx_pos_tables_scope` (`category_code`, `unit_code`),
  KEY `idx_pos_tables_name` (`table_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `tbl_pos_table_rooms` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `category_code` VARCHAR(100) NOT NULL,
  `unit_code` VARCHAR(100) NOT NULL,
  `room_key` VARCHAR(120) NOT NULL,
  `room_name` VARCHAR(160) NOT NULL,
  `tables_json` LONGTEXT NULL,
  `sort_order` INT NOT NULL DEFAULT 0,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `date_recorded` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `date_updated` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `uq_pos_table_rooms_scope` (`category_code`, `unit_code`, `room_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

START TRANSACTION;

-- ---------------------------------------------------------------------
-- 1. Company, business category, business unit
--    The POS reads the first business unit only (get_user_profile.php),
--    so whatever unit was there before (Crab & Crack, Grumpy Joe, ...) is
--    removed and Richwell becomes the only one.
-- ---------------------------------------------------------------------
DELETE FROM tbl_main_corporations WHERE Corp_Code <> 301;
SELECT 301, 'RICHWELL COLLEGES, INC.', 'SAMPLE ADDRESS, PHILIPPINES', '000-000-000-00000', 'Active', 'Not yet sync'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM tbl_main_corporations WHERE Corp_Code = 301);

DELETE FROM tbl_main_business_category WHERE Category_Code <> 'Richwell';
SELECT 'Richwell', 'RICHWELL', 'RICHWELL HOTEL AND RESTAURANT', 91, 33, 182, 'Active', 'Not yet sync'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM tbl_main_business_category WHERE Category_Code = 'Richwell');

DELETE FROM tbl_main_business_units WHERE Unit_Code <> 'BU-24cae516f663';
     Region_Name, Area_Name, Notes, MD, GM, BP, Code_2, Status, Remarks, Date_Open)
SELECT 'Richwell', '301', 'BU-24cae516f663', 'RICHWELL HOTEL AND RESTAURANT', '000-000-000-00000', 'SAMPLE ADDRESS, PHILIPPINES', 'Hotel and Restaurant', 'VAT Registered',
       '', '', '', '', '', '', '', 'Active', 'Not yet sync', CURDATE()
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM tbl_main_business_units WHERE Unit_Code = 'BU-24cae516f663');

-- ---------------------------------------------------------------------
-- 2. Terminal, users, document counters -> Richwell
-- ---------------------------------------------------------------------
UPDATE tbl_pos_terminal_config
SET categoryCode = 'Richwell', unitCode = 'BU-24cae516f663', businessUnitName = 'RICHWELL HOTEL AND RESTAURANT', corpName = 'RICHWELL COLLEGES, INC.',
    machineNumber = '00000000000000', serialNumber = 'SN-0000000000',
    ptuNumber = 'FP000000-0000000000-00000', ptuDateIssued = '01/01/2025', status = 'Active';

     ptuNumber, ptuDateIssued, status, created_at, updated_at)
SELECT 'Richwell', 'BU-24cae516f663', 'RICHWELL HOTEL AND RESTAURANT', '1', 'RICHWELL COLLEGES, INC.', '00000000000000', 'SN-0000000000',
       'FP000000-0000000000-00000', '01/01/2025', 'Active', NOW(), NOW()
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM tbl_pos_terminal_config);

UPDATE tbl_main_users_credentials_business_units
SET category_code = 'Richwell', unit_code = 'BU-24cae516f663';

-- Users: keep the ADMIN login only. ADMIN is (re)activated, every other
-- account is set Inactive (not deleted). The Lightem support account
-- (adminlightem) is left untouched. Make sure you know ADMIN's password.
UPDATE tbl_users_global_assignment SET company = 'RICHWELL HOTEL AND RESTAURANT' WHERE email <> 'adminlightem';
UPDATE tbl_users_global_assignment SET status = 'Active' WHERE email = 'ADMIN';
UPDATE tbl_users_global_assignment SET status = 'Inactive' WHERE email NOT IN ('ADMIN', 'adminlightem');

-- Document counters: keep the row with the highest numbers (so invoice
-- numbers never go backwards) and move it to Richwell.
DELETE c FROM tbl_pos_document_counters c
JOIN (SELECT MAX(next_invoice_no) AS top_invoice FROM tbl_pos_document_counters) x
  ON c.next_invoice_no < x.top_invoice;
UPDATE tbl_pos_document_counters SET Category_Code = 'Richwell', Unit_Code = 'BU-24cae516f663';

SELECT 'Richwell', 'BU-24cae516f663', 3000000001, 4000000001
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM tbl_pos_document_counters WHERE Unit_Code = 'BU-24cae516f663');

-- ---------------------------------------------------------------------
-- 3. Sales (service) types
-- ---------------------------------------------------------------------
UPDATE lkp_sales_type SET deletestatus = 'Inactive' WHERE description IN ('GRAB', 'FOOD PANDA');

SELECT (SELECT COALESCE(MAX(seq), 0) + 1 FROM lkp_sales_type), 'ST-79266940e869', 'ROOM SERVICE', 'Active', '2026032507321651', NOW()
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lkp_sales_type WHERE description = 'ROOM SERVICE');

SELECT (SELECT COALESCE(MAX(seq), 0) + 1 FROM lkp_sales_type), 'ST-7a8c7605815a', 'POOLSIDE', 'Active', '2026032507321651', NOW()
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lkp_sales_type WHERE description = 'POOLSIDE');

SELECT (SELECT COALESCE(MAX(seq), 0) + 1 FROM lkp_sales_type), 'ST-7730b30ca18b', 'BAR', 'Active', '2026032507321651', NOW()
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lkp_sales_type WHERE description = 'BAR');

SELECT (SELECT COALESCE(MAX(seq), 0) + 1 FROM lkp_sales_type), 'ST-12cbd9255ac3', 'LOUNGE', 'Active', '2026032507321651', NOW()
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lkp_sales_type WHERE description = 'LOUNGE');

UPDATE lkp_sales_type SET deletestatus = 'Active' WHERE description IN ('DINE IN', 'TAKE OUT', 'ROOM SERVICE', 'POOLSIDE', 'BAR', 'LOUNGE');

-- Display order: DINE IN > TAKE OUT > ROOM SERVICE > POOLSIDE > BAR > LOUNGE
DELETE FROM tbl_pos_settings WHERE category = 'SalesType' AND description = 'Sales Type Display Order';
SELECT (SELECT COALESCE(MAX(ID), 0) + 1 FROM tbl_pos_settings), 'SalesType', 'Sales Type Display Order',
       CONCAT('[', GROUP_CONCAT(CONCAT('"', s.sales_type_id, '"')
              ORDER BY FIELD(s.description, 'DINE IN', 'TAKE OUT', 'ROOM SERVICE', 'POOLSIDE', 'BAR', 'LOUNGE'), s.seq SEPARATOR ','), ']')
FROM lkp_sales_type s
WHERE s.description IN ('DINE IN', 'TAKE OUT', 'ROOM SERVICE', 'POOLSIDE', 'BAR', 'LOUNGE') AND s.deletestatus = 'Active';

-- ---------------------------------------------------------------------
-- 4. Clear ALL old products, prices and pricing categories
--    (single business unit per database; includes any earlier Richwell seed)
-- ---------------------------------------------------------------------
DELETE FROM tbl_pricing_details;
DELETE FROM tbl_inventory_products_masterlist;
DELETE FROM tbl_pricing_by_sales_type;

-- ---------------------------------------------------------------------
-- 5. Pricing category per sales type (same price everywhere)
-- ---------------------------------------------------------------------

SELECT (SELECT COALESCE(MAX(seq), 0) + 1 FROM tbl_pricing_by_sales_type), 'BU-24cae516f663', s.sales_type_id, 'PC-7ac4a37e4fe5', 'Active', '2026032507321651', NOW()
FROM lkp_sales_type s WHERE s.description = 'DINE IN' ORDER BY s.seq LIMIT 1;

SELECT (SELECT COALESCE(MAX(seq), 0) + 1 FROM tbl_pricing_by_sales_type), 'BU-24cae516f663', s.sales_type_id, 'PC-941c2348fadc', 'Active', '2026032507321651', NOW()
FROM lkp_sales_type s WHERE s.description = 'TAKE OUT' ORDER BY s.seq LIMIT 1;

SELECT (SELECT COALESCE(MAX(seq), 0) + 1 FROM tbl_pricing_by_sales_type), 'BU-24cae516f663', s.sales_type_id, 'PC-44227a409905', 'Active', '2026032507321651', NOW()
FROM lkp_sales_type s WHERE s.description = 'ROOM SERVICE' ORDER BY s.seq LIMIT 1;

SELECT (SELECT COALESCE(MAX(seq), 0) + 1 FROM tbl_pricing_by_sales_type), 'BU-24cae516f663', s.sales_type_id, 'PC-70e65eb31edf', 'Active', '2026032507321651', NOW()
FROM lkp_sales_type s WHERE s.description = 'POOLSIDE' ORDER BY s.seq LIMIT 1;

SELECT (SELECT COALESCE(MAX(seq), 0) + 1 FROM tbl_pricing_by_sales_type), 'BU-24cae516f663', s.sales_type_id, 'PC-cc075e7fc19d', 'Active', '2026032507321651', NOW()
FROM lkp_sales_type s WHERE s.description = 'BAR' ORDER BY s.seq LIMIT 1;

SELECT (SELECT COALESCE(MAX(seq), 0) + 1 FROM tbl_pricing_by_sales_type), 'BU-24cae516f663', s.sales_type_id, 'PC-3a153bfe284e', 'Active', '2026032507321651', NOW()
FROM lkp_sales_type s WHERE s.description = 'LOUNGE' ORDER BY s.seq LIMIT 1;


