-- ---------------------------------------------------------------------
-- 9. Statutory discounts active on every sales type
-- ---------------------------------------------------------------------
SELECT d.id, s.sales_type_id, 1, NULL, '2026032507321651'
FROM lkp_discount_type d
JOIN lkp_sales_type s ON s.description IN ('DINE IN', 'TAKE OUT', 'ROOM SERVICE', 'POOLSIDE', 'BAR', 'LOUNGE') AND s.deletestatus = 'Active'
WHERE d.discount_name IN ('Senior Citizen', 'PWD (Persons with Disability)', 'Solo Parent', 'National Athlete/Coach')
ON DUPLICATE KEY UPDATE is_active = 1;

-- ---------------------------------------------------------------------
-- 10. Hotel other charges (disabled until turned on in Settings)
-- ---------------------------------------------------------------------

SELECT 'POS', 'CORKAGE FEE', 500, 'Fixed', 0
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM tbl_pos_list_of_other_charges WHERE particulars = 'CORKAGE FEE');

SELECT 'POS', 'BREAKAGE / DAMAGE', 0, 'Fixed', 0
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM tbl_pos_list_of_other_charges WHERE particulars = 'BREAKAGE / DAMAGE');

SELECT 'POS', 'LOST KEY CARD', 300, 'Fixed', 0
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM tbl_pos_list_of_other_charges WHERE particulars = 'LOST KEY CARD');


COMMIT;

