SELECT 'business units' AS item, COUNT(*) AS total FROM tbl_main_business_units
UNION ALL SELECT 'richwell sales types', COUNT(*) FROM tbl_pricing_by_sales_type WHERE busunitcode = 'BU-24cae516f663'
